use uuid::Uuid;

/// Central storage key generator adhering to PACE TDD 9.1 layout.
/// All services (Rust API, Render Worker, Python Audio Worker) adhere to these exact paths.
pub struct StorageKeys;

impl StorageKeys {
    /// Original uploaded media file (JPEG, PNG, WebP)
    pub fn media_original(user_id: &Uuid, project_id: &Uuid, media_id: &Uuid, ext: &str) -> String {
        let clean_ext = ext.trim_start_matches('.');
        format!("u/{user_id}/p/{project_id}/media/{media_id}/original.{clean_ext}")
    }

    /// Long side 1280 px preview WebP generated by browser Web Worker
    pub fn media_preview(user_id: &Uuid, project_id: &Uuid, media_id: &Uuid) -> String {
        format!("u/{user_id}/p/{project_id}/media/{media_id}/preview.webp")
    }

    /// Long side 320 px thumbnail WebP generated by browser Web Worker
    pub fn media_thumb(user_id: &Uuid, project_id: &Uuid, media_id: &Uuid) -> String {
        format!("u/{user_id}/p/{project_id}/media/{media_id}/thumb.webp")
    }

    /// Blurred background copy for Fit Blur mode
    pub fn media_preview_blur(user_id: &Uuid, project_id: &Uuid, media_id: &Uuid) -> String {
        format!("u/{user_id}/p/{project_id}/media/{media_id}/preview-blur.webp")
    }

    /// Original uploaded narration audio file
    pub fn audio_original(user_id: &Uuid, project_id: &Uuid, media_id: &Uuid, ext: &str) -> String {
        let clean_ext = ext.trim_start_matches('.');
        format!("u/{user_id}/p/{project_id}/audio/{media_id}/original.{clean_ext}")
    }

    /// Compressed narration Opus file (NAR-06)
    pub fn audio_opus(user_id: &Uuid, project_id: &Uuid, media_id: &Uuid) -> String {
        format!("u/{user_id}/p/{project_id}/audio/{media_id}/audio.opus")
    }

    /// 16 kHz mono transcription audio
    pub fn audio_asr(user_id: &Uuid, project_id: &Uuid, media_id: &Uuid) -> String {
        format!("u/{user_id}/p/{project_id}/audio/{media_id}/asr.mp3")
    }

    /// Waveform peak JSON data for UI
    pub fn audio_peaks(user_id: &Uuid, project_id: &Uuid, media_id: &Uuid) -> String {
        format!("u/{user_id}/p/{project_id}/audio/{media_id}/peaks.json")
    }

    /// Audio folder prefix for cleanup/replacement
    pub fn project_audio_prefix(user_id: &Uuid, project_id: &Uuid) -> String {
        format!("u/{user_id}/p/{project_id}/audio/")
    }

    /// Uploaded background music track (`MUS-01`)
    pub fn music_original(user_id: &Uuid, project_id: &Uuid, media_id: &Uuid, ext: &str) -> String {
        let clean_ext = ext.trim_start_matches('.');
        format!("u/{user_id}/p/{project_id}/music/{media_id}/original.{clean_ext}")
    }

    /// Music folder prefix for cleanup/replacement
    pub fn project_music_prefix(user_id: &Uuid, project_id: &Uuid) -> String {
        format!("u/{user_id}/p/{project_id}/music/")
    }

    /// Final exported video MP4
    pub fn export_mp4(
        user_id: &Uuid,
        project_id: &Uuid,
        export_id: &Uuid,
        name: &str,
        resolution: &str,
    ) -> String {
        let safe_name = name
            .chars()
            .map(|c| if c.is_alphanumeric() || c == '-' || c == '_' { c } else { '-' })
            .collect::<String>();
        format!("u/{user_id}/p/{project_id}/exports/{export_id}/pace-{safe_name}-{resolution}.mp4")
    }

    /// Content-addressed cached video segment for M8 incremental re-renders
    pub fn render_segment_cache(user_id: &Uuid, project_id: &Uuid, cache_key: &str) -> String {
        format!("u/{user_id}/p/{project_id}/cache/seg-{cache_key}.mp4")
    }

    /// Project prefix for cascade deletion
    pub fn project_prefix(user_id: &Uuid, project_id: &Uuid) -> String {
        format!("u/{user_id}/p/{project_id}/")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_storage_keys_format() {
        let u = Uuid::parse_str("00000000-0000-0000-0000-000000000001").unwrap();
        let p = Uuid::parse_str("00000000-0000-0000-0000-000000000002").unwrap();
        let m = Uuid::parse_str("00000000-0000-0000-0000-000000000003").unwrap();

        assert_eq!(
            StorageKeys::media_original(&u, &p, &m, "png"),
            "u/00000000-0000-0000-0000-000000000001/p/00000000-0000-0000-0000-000000000002/media/00000000-0000-0000-0000-000000000003/original.png"
        );

        assert_eq!(
            StorageKeys::media_thumb(&u, &p, &m),
            "u/00000000-0000-0000-0000-000000000001/p/00000000-0000-0000-0000-000000000002/media/00000000-0000-0000-0000-000000000003/thumb.webp"
        );

        assert_eq!(
            StorageKeys::audio_original(&u, &p, &m, "mp3"),
            "u/00000000-0000-0000-0000-000000000001/p/00000000-0000-0000-0000-000000000002/audio/00000000-0000-0000-0000-000000000003/original.mp3"
        );
    }
}

